class Solution {
    public int maximumScore(int a,int b,int c){
        int total=a+b+c,maximum=Math.max(a,Math.max(b,c));
        return Math.min(total-maximum,total/2);
    }
}

code.kotlin:
class Solution {
    fun maximumScore(a:Int,b:Int,c:Int):Int{
        val total=a+b+c;
        val maximum=maxOf(a,b,c);
        return minOf(total-maximum,total/2)
    }
}

